    receive() external payable {}

    function run(bool makeOwner) public payable {
        uint256 preBal = address(c).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted || address(c).balance == 0);
    }
